head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnIndex]<br/>Body Column 의 ID 를 사용하여 특정 Body Column 의 인덱스값을 반환합니다.",
    "validation" : [
        "Body 영역이 MultiLine 구조여도 모든 Column 은 고유의 인덱스값을 가지며, 인덱스값은 좌상단부터 우하단 순서로 설정되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (MultiLine 구성)
//  - 한 레코드(Row)를 2개의 Line 으로 표시
//    Line1 : name(colIndex 0) + age(colIndex 1)
//    Line2 : dept(colIndex 2) + memo(colIndex 3)
//  - header / gBody 에 각각 <w2:row> 를 2개 두면 한 레코드가 2 Line 으로 렌더됨
//  - 엔진 layoutController : 단일 colIdx 카운터를 row→column 문서 순서대로 순회하며
//    bodyIdColIndexMap[colId] = colIdx 로 인덱스를 부여 (colIdx 0,1,2,3 ...)
//  - 따라서 인덱스는 좌상단(Line1 좌→우)부터 우하단(Line2 좌→우) 순서로 고유하게 설정됨
//    name=0, age=1, dept=2, memo=3
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="MultiLine 2 Line 구성: Line1=name(0)·age(1) / Line2=dept(2)·memo(3) — 인덱스는 좌상단부터 우하단 순서로 고유 부여"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="age" name="age" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "age": "30", "dept": "영업", "memo": "메모0" },
        { "name": "Jane", "age": "28", "dept": "기획", "memo": "메모1" },
        { "name": "Mike", "age": "41", "dept": "개발", "memo": "메모2" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (MultiLine : header/gBody 각각 <w2:row> 2개)
    //  마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnIndex MultiLine 테스트 그리드"></w2:caption>';
    // Header : Line1 = name + age / Line2 = dept + memo
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol_name" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_age" value="나이"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol_dept" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_memo" value="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : Line1 = name(0) + age(1) / Line2 = dept(2) + memo(3)
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // colIndex 0 : name (text)
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // colIndex 1 : age (text)
    strTarget += '<w2:column width="*" style="" inputType="text" id="age" dataList="age"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // colIndex 2 : dept (text)  (Line2 배치)
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    // colIndex 3 : memo (text), width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getColumnIndex 확인 : par_columnId 의 Body Column ID 로 호출 → 해당 Column 인덱스 반환
//  - Line1 컬럼(name,age) / Line2 컬럼(dept,memo) 모두 고유 인덱스로 정확한 값이 반환됨
//  - 인덱스는 좌상단부터 우하단 순서 : name=0, age=1, dept=2, memo=3
scwin.btn_getColumnIndex_onclick = function () {
    let colId = par_columnId.getValue();
    let rtn = target1.getColumnIndex(colId);
    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnIndex(" + colId + ") : " + rtn);
}
